"""Exact predecessor metadata projection; generated bytes only, no source data."""
import ast
import hashlib
import json
from pathlib import Path

import pytest


def _owner():
    path = Path(__file__).resolve().parents[4] / "scripts/research/a2/data/consensus_account_inputs.py"
    tree = ast.parse(path.read_text(encoding="utf-8"))
    nodes = [
        node for node in tree.body
        if isinstance(node, (ast.ClassDef, ast.FunctionDef))
        and node.name in ("_JsonProjection", "completion_predecessor_reader")
    ]
    assert {node.name for node in nodes} == {"_JsonProjection", "completion_predecessor_reader"}

    def require(ok, reason):
        if not ok:
            raise ValueError(reason)

    scope = dict(Path=Path, json=json, require=require)
    exec(compile(ast.Module(body=nodes, type_ignores=[]), str(path), "exec"), scope)
    return scope["completion_predecessor_reader"]


def _ref(path):
    return dict(path=str(path), sha256=hashlib.sha256(path.read_bytes()).hexdigest())


def _bundle(ref):
    return dict(exact_historical_python_code_custody_transport=[
        dict(predecessor_source_contract_ref=ref)
    ])


def test_declared_large_reference_projection_skips_poison_payload(tmp_path):
    path = tmp_path / "declared.json"
    refs = [dict(path=f"D:/synthetic/source/{n}.py", sha256="a" * 64) for n in range(800)]
    encoded = json.dumps(refs)
    assert 65536 < len(encoded.encode()) < 2 * 1024 * 1024
    path.write_text(
        '{"schema":"SOURCE_CONTRACT","status":"PASSED","source_refs":'
        + encoded
        + ',"never_decode_payload":DO_NOT_DECODE_THIS_VALUE}',
        encoding="utf-8",
    )
    with pytest.raises(json.JSONDecodeError):
        json.loads(path.read_text(encoding="utf-8"))
    reference = _ref(path)
    pins = []

    def pin(ref):
        assert ref == reference and _ref(path) == reference
        pins.append(ref)
        return path

    def unchanged_reader(ref):
        raise AssertionError("declared metadata must be projected")

    read = _owner()(_bundle(reference), pin, unchanged_reader)
    projected = read(reference)
    assert projected == dict(schema="SOURCE_CONTRACT", status="PASSED", source_refs=refs)
    assert read(reference) is projected
    assert len(pins) == 1


@pytest.mark.parametrize("mutation", ["different_path", "different_sha"])
def test_undeclared_exact_reference_keeps_original_reader(tmp_path, mutation):
    path = tmp_path / "declared.json"
    path.write_text('{"schema":"ONE","status":"PASS","source_refs":[]}', encoding="utf-8")
    reference = _ref(path)
    other = dict(reference)
    if mutation == "different_path":
        other_path = tmp_path / "other.json"
        other_path.write_bytes(path.read_bytes())
        other = _ref(other_path)
    else:
        other["sha256"] = "f" * 64
    calls = []

    def pin(ref):
        raise AssertionError("undeclared references cannot use the projection pin")

    def unchanged_reader(ref):
        calls.append(ref)
        return {"original_reader": True}

    read = _owner()(_bundle(reference), pin, unchanged_reader)
    assert read(other) == {"original_reader": True}
    assert calls == [other]


def test_predecessor_reference_value_limit_is_enforced_before_decode(tmp_path):
    path = tmp_path / "too_large.json"
    path.write_text(
        '{"schema":"SOURCE_CONTRACT","status":"PASSED","source_refs":["'
        + "x" * (2 * 1024 * 1024)
        + '"],"never_decode_payload":DO_NOT_DECODE_THIS_VALUE}',
        encoding="utf-8",
    )
    reference = _ref(path)

    def pin(ref):
        assert ref == reference and _ref(path) == reference
        return path

    def unchanged_reader(ref):
        raise AssertionError("declared ref must retain bounded projection")

    read = _owner()(_bundle(reference), pin, unchanged_reader)
    with pytest.raises(ValueError, match="SOURCE_JSON_METADATA_VALUE_TOO_LARGE"):
        read(reference)